def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

# Check if F_k - F_j = L_100
L_100 = (fib(99) + fib(101))
f_vals = [fib(k) for k in range(126)]
for k in range(2, 126):
    for j in range(2, k):
        if f_vals[k] - f_vals[j] == L_100:
            print(f"F_{k} - F_{j} = L_{100} where k={k}, j={j}")
